INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, 0.2, 0.2, 0, 104331, "", 308, 1, 308008, "nop_talk_arm_crossed_loop2", "nop_talk_arm_crossed2");
