INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (11, 0, 0, 8, 102711, 0.5, 311, 0, 311002, 0, "この広い会場のどこかに\nあのおかたの存在を感じますわ……");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (91, "", "", "", 311002, "", 311, "", 311003, "", "");
