INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, 0.2, 0, 0, 100911, "", 311, 1, 311005, "nop_11_anna_huhuStand_loop", "nop_11_anna_huhuStand_in");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (11, 0, 0, 8, 100911, 0.5, 311, 0, 311006, 0, "疼く……疼くぞ！\n我が魔眼が新たなる年を祝えと……！");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (91, "", "", "", 311006, "", 311, "", 311007, "", "");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, 0.2, "", 1, 100911, "", 311, "", 311008, "", "nop_11_anna_huhuStand_loop");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, 0.2, "", 1, 101311, "", 311, "", 311009, "", "nop_talk_joy2");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (11, 0, 0, 8, 101311, 0.5, 311, 0, 311010, 0, "アンナたそアンナたそ！\nおせち料理、美味しそうですぞ！\nさあ、おあがりよ！！");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (91, "", "", "", 311010, "", 311, "", 311011, "", "");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, 0.2, "", 1, 101311, "", 311, "", 311012, "", "nop_idle_joy_normal");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, 0.2, "", 1, 105111, "", 311, "", 311013, "", "nop_talk_thinking");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (11, 0, 0, 8, 105111, 0.5, 311, 0, 311014, 0, "医食同源……って知ってるかしら？\n長寿を願う料理には、なにかしらの\n効能があるものも多いのよ。");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (91, "", "", "", 311014, "", 311, "", 311015, "", "");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, 0.2, "", 1, 105111, "", 311, "", 311016, "", "nop_idle_thinking");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (11, 0, 0, 8, 101831, 0.5, 312, 0, 312001, 0, "素敵な新年会ね～\n他の学校の人たちも来ているようだし\nお話を伺いに行こうかしら？");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, 0.2, "", 1, 101831, "", 312, "", 312002, "", "nop_talk_joy1");
