INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, 0.2, "", 1, 101831, "", 312, 1, 312004, "", "nop_idle_joy1");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (11, 0, 0, 8, 101611, 0.5, 312, 0, 312005, 0, "見て見てミサキっち！\nあそこの料理すっごく美味しそう！");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, 0.2, "", 1, 101611, "", 312, "", 312006, "", "nop_talk_surprise_kira");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (91, "", "", "", 312005, "", 312, "", 312007, "", "");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, 0.2, "", 1, 101611, "", 312, 1, 312008, "", "nop_idle_surprise_kira");
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (11, 0, 0, 8, 105011, 0.5, 312, 0, 312009, 0, "えー？　でもあれって野菜じゃない？\n別に、大人のレディだから\n食べられないわけじゃないけど？");
