INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, 0.2, "", 1, 103731, "", 506, "", 506014, "", "nop_06_tomo_talk_anger");
