INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, 0.2, 0, 0, 111031, "", 517, 1, 517038, "nop_17_yuni_talk_nofaith_loop", "nop_17_yuni_talk_nofaith");
